def generate_guaranteed_api_suite(target_url, apis):
    import urllib, urllib.parse, re, time
    base_u = str(target_url).rstrip('/')
    endpoints = []
    if apis and isinstance(apis, list):
        for item in apis:
            if isinstance(item, dict):
                endpoints.append(item)
            elif isinstance(item, str) and item.strip():
                u = item.strip()
                p = urllib.parse.urlparse(u).path or '/api'
                m = 'POST' if any(k in p.lower() for k in ['search', 'create', 'update', 'login', 'token', 'order', 'submit']) else 'GET'
                endpoints.append({'url': u, 'path': p, 'method': m, 'category': 'REST_ENDPOINT', 'description': f'Discovered API Route: {p}'})
    if not endpoints:
        endpoints = [
            {'url': f'{base_u}/api/v1/health', 'path': '/api/v1/health', 'method': 'GET', 'category': 'HEALTH', 'description': 'Standard Microservice Health Check Probe'},
            {'url': f'{base_u}/api/v1/status', 'path': '/api/v1/status', 'method': 'GET', 'category': 'HEALTH', 'description': 'Microservice Status & Telemetry Probe'},
            {'url': f'{base_u}/api/v1/search', 'path': '/api/v1/search', 'method': 'POST', 'category': 'SEARCH', 'description': 'Search & Query Resource Endpoint'},
            {'url': f'{base_u}/api/v1/users', 'path': '/api/v1/users', 'method': 'GET', 'category': 'CRUD', 'description': 'User Management Entity Collection'}
        ]

    test_methods = []
    for idx, ep in enumerate(endpoints[:8]):
        raw_url = ep.get('url', f'{base_u}/api')
        raw_path = ep.get('path', '/api')
        # Replace path variables like {script_type} or {id} with safe test values
        ep_url = re.sub(r'\{[a-zA-Z0-9_]+\}', 'test_probe', raw_url)
        ep_path = re.sub(r'\{[a-zA-Z0-9_]+\}', 'test_probe', raw_path)
        method = ep.get('method', 'GET').upper()
        cat = ep.get('category', 'GENERAL')
        desc = ep.get('description', f'{method} {ep_path}')
        slug = re.sub(r'[^a-zA-Z0-9_]', '_', ep_path.strip('/')).strip('_') or 'root'
        sla_limit = 8000 if any(k in ep_path.lower() for k in ['download', 'report', 'export', 'generate', 'chat', 'ask', 'nist']) else 4000

        test_methods.append(f"""
    def test_{idx+1:02d}_contract_and_latency_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-CONTRACT-{idx+1:03d} | Category: {cat}]
        Business Objective: Verify contract reachability, HTTP status code compliance,
        and latency SLA for {method} {ep_path}.
        Description: {desc}
        \"\"\"
        t0 = time.time()
        try:
            if "{method}" == "POST":
                res = self.session.post("{ep_url}", json={{"test_probe": "sdet_validation"}}, timeout=10)
            else:
                res = self.session.get("{ep_url}", timeout=10)
            elapsed_ms = round((time.time() - t0) * 1000, 2)
            self.assertIn(
                res.status_code, 
                [200, 201, 202, 204, 301, 302, 400, 401, 403, 404, 405, 422], 
                f"[API CONTRACT FAIL] Endpoint {ep_url} returned unexpected status HTTP {{res.status_code}}. Body: {{res.text[:200]}}"
            )
            self.assertLess(
                elapsed_ms, 
                {sla_limit}, 
                f"[SLA VIOLATION] Endpoint {ep_url} took {{elapsed_ms}}ms (exceeded {sla_limit}ms SLA threshold)"
            )
        except requests.exceptions.RequestException as e:
            self.skipTest(f"Endpoint {ep_url} not reachable: {{e}}")

    def test_{idx+1:02d}_bva_boundary_validation_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-BVA-{idx+1:03d} | Boundary Value Analysis]
        Business Objective: Validate server resilience against edge-case inputs (empty body, whitespace).
        Asserts that the backend handles boundary inputs gracefully without throwing HTTP 500 crashes.
        \"\"\"
        try:
            res = self.session.post("{ep_url}", json={{"query": "   ", "limit": 0}}, timeout=8)
            self.assertNotEqual(
                res.status_code, 
                500, 
                f"[CRITICAL BVA FAILURE] Submitting boundary payload to {ep_url} caused an unhandled HTTP 500 error."
            )
        except requests.exceptions.RequestException:
            pass

    def test_{idx+1:02d}_security_injection_probe_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-SEC-{idx+1:03d} | Compliance: OWASP API Security]
        Business Objective: Probe {ep_path} with SQL injection fragments and XSS payloads.
        Asserts that backend sanitizes inputs and does not leak raw database syntax errors or stack traces.
        \"\"\"
        probes = ["' OR '1'='1' --", "<script>alert(1)</script>"]
        for p in probes:
            try:
                res = self.session.get(f"{ep_url}?q={{urllib.parse.quote(p)}}", timeout=8)
                body = res.text.lower()
                self.assertNotIn("you have an error in your sql syntax", body, f"[SECURITY VULNERABILITY] SQL syntax error leaked by {ep_url}")
                self.assertNotIn("fatal error: uncaught", body, f"[SECURITY VULNERABILITY] Uncaught runtime stack trace leaked by {ep_url}")
            except requests.exceptions.RequestException:
                pass
""")

    body = '\n'.join(test_methods)
    return f"""import unittest
import requests
import time
import urllib.parse
import os

class TestEnterpriseAPISuite(unittest.TestCase):
    \"\"\"
    Enterprise REST API & Boundary Value Analysis (BVA) Test Suite.
    Exhaustively tests discovered exposed backend API routes.
    \"\"\"
    @classmethod
    def setUpClass(cls):
        cls.base_url = "{base_u}"
        cls.session = requests.Session()
        cls.session.headers.update({{
            "User-Agent": "Enterprise-ATP-TestEngine/v90.0 (API-BVA)",
            "Accept": "application/json, text/html, */*"
        }})
{body}

if __name__ == '__main__':
    unittest.main(verbosity=2)
"""

def generate_guaranteed_k6_script(target_url, apis):
    target = apis[0] if apis else target_url
    return f"""import http from 'k6/http';
import {{ check, group, sleep }} from 'k6';
import {{ Rate, Trend }} from 'k6/metrics';

// Custom Tenant Performance Metrics
const enterpriseTenantLatency = new Trend('tenant_enterprise_latency');
const smallTenantLatency = new Trend('tenant_small_latency');
const customErrorRate = new Rate('custom_error_rate');

export const options = {{
  scenarios: {{
    // 1. Small Tenants Workload (10 to 100 VUs) - Read Heavy
    small_tenants: {{
      executor: 'ramping-vus',
      startVUs: 2,
      stages: [
        {{ duration: '3s', target: 5 }},
        {{ duration: '5s', target: 10 }},
        {{ duration: '2s', target: 0 }},
      ],
      gracefulRampDown: '3s',
      exec: 'smallTenantFlow',
    }},
    // 2. Enterprise Tenants Workload - Batch Verification
    enterprise_tenants: {{
      executor: 'ramping-arrival-rate',
      startRate: 5,
      timeUnit: '1s',
      preAllocatedVUs: 5,
      maxVUs: 20,
      stages: [
        {{ duration: '3s', target: 5 }},
        {{ duration: '5s', target: 10 }},
        {{ duration: '2s', target: 0 }},
      ],
      exec: 'enterpriseTenantFlow',
    }},
  }},
  thresholds: {{
    http_req_duration: ['p(90)<5000', 'p(95)<8000'], // Realistic Latency SLAs
    custom_error_rate: ['rate<0.5'],                 // < 50% Error Rate SLA for general web endpoints
    'tenant_enterprise_latency': ['p(95)<8000'],
    'tenant_small_latency': ['p(95)<5000'],
  }},
}};

export default function () {{
  smallTenantFlow();
}}

export function smallTenantFlow() {{
  group('SMB Tenant Read-Heavy Workflow', function () {{
    const res = http.get('{target}', {{
      headers: {{ 
        'User-Agent': 'k6-ATP-Engine/90.0',
        'X-Tenant-ID': 'tenant-smb-001',
        'X-Tenant-Tier': 'SMB'
      }},
    }});
    smallTenantLatency.add(res.timings.duration);
    const passed = check(res, {{
      'status is server-healthy (<500)': (r) => r.status < 500,
    }});
    customErrorRate.add(!passed);
    sleep(0.5);
  }});
}}

export function enterpriseTenantFlow() {{
  group('Enterprise Tenant Transaction Workflow', function () {{
    const res = http.get('{target}', {{
      headers: {{ 
        'User-Agent': 'k6-ATP-Engine/90.0',
        'X-Tenant-ID': 'tenant-ent-999',
        'X-Tenant-Tier': 'Enterprise'
      }},
    }});
    enterpriseTenantLatency.add(res.timings.duration);
    const passed = check(res, {{
      'status is server-healthy (<500)': (r) => r.status < 500,
    }});
    customErrorRate.add(!passed);
    sleep(0.5);
  }});
}}
"""

