    def update_pipeline_state(self, status="running", progress=0, steps=None, current_task="", current_command="", result=None, error=None, gate_data=None, chunking=False, warnings=None, attempt_info=None, current_prompt=None, llm_active=None, current_response=None):
        curr_time = time.time()
        old_data = {}
        status_file = "artifacts/logs/task_status.json"
        
        # 1. [UNICODE:26A1] Read and merge existing state to prevent field dropping [UNICODE:26A1]
        if os.path.exists(status_file):
            try:
                with open(status_file, "r", encoding="utf-8") as f:
                    old_data = json.load(f)
            except Exception:
                old_data = {}

        # [UNICODE:26A1] Safe attribute lookup with fallback to disk and curr_time [UNICODE:26A1]
        start_ts = getattr(self, 'pipeline_start_time', None)
        if not start_ts:
            start_ts = old_data.get("start_time") or curr_time
            self.pipeline_start_time = start_ts

        # Preserve steps if not passed in current update
        merged_steps = steps if steps is not None else old_data.get("steps", {})
        
        # Preserve result data if not passed in current update
        merged_result = result if result is not None else old_data.get("result", None)
        
        # Preserve warnings and attempt info
        merged_warnings = warnings if warnings is not None else old_data.get("warnings", None)
        merged_attempt = attempt_info if attempt_info is not None else old_data.get("attempt_info", None)
        merged_gate = gate_data if gate_data is not None else old_data.get("gate_data", None)

        payload = {
            "status": status,
            "progress": progress if progress > 0 else old_data.get("progress", 0),
            "current_task": current_task or old_data.get("current_task", "Ready"),
            "current_command": current_command or old_data.get("current_command", "Idle."),
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "start_time": start_ts,
            "chunking": chunking,
            "current_prompt": current_prompt if current_prompt is not None else old_data.get("current_prompt", ""),
            "current_response": current_response if current_response is not None else old_data.get("current_response", ""),
            "llm_active": llm_active if llm_active is not None else old_data.get("llm_active", False)
        }

        if merged_steps:
            payload["steps"] = merged_steps
        if merged_result:
            payload["result"] = merged_result
        if error:
            payload["error"] = error
        elif "error" in old_data and status in ["error", "failed"]:
            payload["error"] = old_data["error"]
        if merged_gate:
            payload["gate_data"] = merged_gate
        if merged_warnings:
            payload["warnings"] = merged_warnings
        if merged_attempt:
            payload["attempt_info"] = merged_attempt

        # 2. [UNICODE:26A1] Precise Execution Duration Locking Logic [UNICODE:26A1]
        if status in ["completed", "failed", "error"]:
            # If already locked in old_data, preserve exact timestamp without drift
            if "total_elapsed_seconds" in old_data and old_data["total_elapsed_seconds"]:
                payload["total_elapsed_seconds"] = old_data["total_elapsed_seconds"]
                payload["end_time"] = old_data.get("end_time", curr_time)
            else:
                payload["total_elapsed_seconds"] = round(curr_time - start_ts, 1)
                payload["end_time"] = curr_time
        elif status == "paused_gate":
            # Record time elapsed up to gate pause
            payload["current_elapsed_seconds"] = round(curr_time - start_ts, 1)
            payload["gate_paused_at"] = curr_time
        else:
            # Active running state
            payload["current_elapsed_seconds"] = round(curr_time - start_ts, 1)

        # 3. [UNICODE:26A1] Atomic Write Routine to Prevent Polling Read Collisions [UNICODE:26A1]
        try:
            os.makedirs(os.path.dirname(status_file), exist_ok=True)
            temp_file = f"{status_file}.tmp"
            with open(temp_file, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=4)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_file, status_file)
        except Exception:
            with open(status_file, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=4)

    def extract_apis(self, target_url=None, crawled_doms=None):
        """
        Industrial-grade active & passive API crawler.
        Probes OpenAPI/Swagger/GraphQL specs, scrapes JS bundles, intercepts network traffic, and parses HTML forms.
        """
        perf_logs = []
        if self.driver:
            try:
                perf_logs = self.driver.get_log("performance")
            except Exception:
                pass

        base_u = target_url or (self.driver.current_url if self.driver else "http://localhost:8000")
        try:
            try:
                from engines.api_crawler import EnterpriseAPICrawler
            except ImportError:
                from aspice_qa_framework.engines.api_crawler import EnterpriseAPICrawler

            crawler = EnterpriseAPICrawler(
                base_url=base_u,
                session=requests.Session(),
                trace_callback=self.emit_trace,
                timeout=5.0
            )
            catalog = crawler.crawl_and_analyze(crawled_doms=crawled_doms, performance_logs=perf_logs)
            self.api_catalog = catalog
            return [ep["url"] for ep in catalog]
        except Exception as e:
            self.emit_trace("WARNING", f"Advanced API crawler notice: {e}; falling back to passive network logs.")
            apis = []
            for entry in perf_logs:
                try:
                    msg = json.loads(entry['message'])['message']
                    if msg.get('method') == 'Network.requestWillBeSent':
                        req = msg.get('params', {}).get('request', {})
                        url = req.get('url', '')
                        method = req.get('method', 'GET')
                        if any(k in url.lower() for k in ["api", "graphql", "v1", "v2", "json", ".php", "endpoint"]):
                            apis.append(url)
                except Exception:
                    continue
            return list(set(apis)) if apis else [f"{base_u.rstrip('/')}/api/v1/health"]

    def wait_for_page_ready(self, timeout=25, poll_frequency=0.35):
        """
        Industrial-grade full page load and dynamic hydration waiting routine.
        Guarantees:
        1. document.readyState === 'complete'
        2. Anti-bot / Cloudflare Challenge clearance (if present)
        3. Network Idle: jQuery, Angular, Fetch & active XHR requests are zero
        4. DOM Mutation & Virtual DOM Hydration stabilization (React, Vue, Angular)
        5. Loader, spinner, and skeleton dismissal via bypass_loaders_and_scroll()
        """
        if not self.driver:
            return True
            
        start_t = time.time()
        self.log_selenium_action("WAIT_PAGE_READY", f"Waiting for full page load and hydration (timeout: {timeout}s)...")
        
        # 1. Wait for document.readyState == 'complete'
        try:
            WebDriverWait(self.driver, timeout, poll_frequency=poll_frequency).until(
                lambda d: d.execute_script("return document.readyState") == "complete"
            )
        except Exception:
            self.log_selenium_action("PAGE_LOAD_TIMEOUT", f"document.readyState did not reach 'complete' within {timeout}s; proceeding with best-effort stabilization.")

        # 2. Check and wait for Cloudflare / Anti-bot challenge clearance if detected
        try:
            for _ in range(int(min(timeout, 10) / 1.0)):
                title_low = (self.driver.title or "").lower()
                source_low = (self.driver.page_source or "").lower()[:2000]
                if any(phrase in title_low or phrase in source_low for phrase in ["just a moment", "checking your browser", "cloudflare", "ddos protection"]):
                    self.log_selenium_action("BOT_CHALLENGE", "Cloudflare/Anti-bot challenge detected. Waiting for clearance...")
                    time.sleep(1.5)
                else:
                    break
        except Exception:
            pass

        # 3. Wait for Network Idle (active AJAX / Fetch / XHR requests)
        try:
            network_script = """
                const jqIdle = (typeof jQuery === 'undefined' || jQuery.active === 0);
                const ngIdle = (typeof angular === 'undefined' || !angular.element || !angular.element(document.body).injector || angular.element(document.body).injector().get('$http').pendingRequests.length === 0);
                return jqIdle && ngIdle;
            """
            WebDriverWait(self.driver, min(timeout, 8), poll_frequency=poll_frequency).until(
                lambda d: d.execute_script(network_script) is True
            )
        except Exception:
            pass

        # 4. DOM Mutation & Hydration Stabilization Check (React/Vue/Angular)
        try:
            prev_len = self.driver.execute_script("return (document.body ? document.body.innerHTML.length : 0);")
            for _ in range(4):
                time.sleep(0.3)
                curr_len = self.driver.execute_script("return (document.body ? document.body.innerHTML.length : 0);")
                if abs(curr_len - prev_len) < 50:
                    break
                prev_len = curr_len
        except Exception:
            pass

        # 5. Loader, spinner, and skeleton dismissal + smart scroll
        try:
            self.bypass_loaders_and_scroll()
        except Exception:
            pass

        elapsed = round(time.time() - start_t, 2)
        self.log_selenium_action("PAGE_READY", f"Page fully loaded, hydrated, and stabilized in {elapsed}s.")
        return True

    def bypass_loaders_and_scroll(self):
        try:
            removed_count = self.driver.execute_script("""
                const loaders = document.querySelectorAll('.spinner, .loading, #loader, [aria-busy="true"], .skeleton, .overlay, .modal-backdrop');
                let count = loaders.length;
                for (var i = 0; i < loaders.length; i++) if (loaders[i] && loaders[i].parentNode) loaders[i].parentNode.removeChild(loaders[i]);
                if (document.body) document.body.style.overflow = 'auto';
                return count;
            """)
            if removed_count and removed_count > 0:
                self.log_selenium_action("LOADER_BYPASS", f"Removed {removed_count} active overlay spinner(s) from DOM.")
            
            last_height = self.driver.execute_script("return document.body.scrollHeight")
            for i in range(3):
                self.driver.execute_script("window.scrollTo(0, document.body.scrollHeight);")
                time.sleep(0.8)
                new_height = self.driver.execute_script("return document.body.scrollHeight")
                self.log_selenium_action("SMART_SCROLL", f"Pass {i+1}/3 scrolled to {new_height}px (triggering lazy loaders).", f"driver.execute_script('window.scrollTo(0, {new_height})')")
                if new_height == last_height: break
                last_height = new_height
            self.driver.execute_script("window.scrollTo(0, 0);")
        except Exception as e:
            self.log_selenium_action("ERROR", f"Loader bypass / scroll warning: {str(e)}")

    def clean_page_text_for_extraction(self, html_source, max_chars=12000):
        """
        Aggressively strips noise and boilerplate (nav, footer, aside, form, header, cookie notices, scripts)
        to prevent boilerplate contamination ('Privacy Policy', 'Login', etc.) from polluting substantive content.
        """
        if not html_source:
            return ""
        try:
            clean_soup = BeautifulSoup(html_source, "html.parser")
            for tag in clean_soup(["script", "style", "nav", "footer", "aside", "form", "header", "noscript", "svg", "iframe"]):
                tag.decompose()
            for noise in clean_soup.find_all(attrs={"class": re.compile(r"cookie|banner|modal|popup|sidebar|footer|compliance|disclaimer|policy", re.I)}):
                noise.decompose()
            text = clean_soup.get_text(separator="\n", strip=True)
            lines = [line.strip() for line in text.splitlines() if len(line.strip()) > 3]
            cleaned = "\n".join(lines)
            return cleaned[:max_chars]
        except Exception:
            return ""

    def parse_llm_json_response(self, raw_text, default_factory=dict):
        """Resilient JSON extractor that parses markdown fences or raw JSON objects."""
        if not raw_text:
            return default_factory()
        clean_text = re.sub(r'<think>.*?</think>', '', str(raw_text), flags=re.DOTALL).strip()
        if "```" in clean_text:
            match = re.search(r'```(?:json)?\s*\n?(.*?)```', clean_text, re.DOTALL | re.IGNORECASE)
            if match:
                clean_text = match.group(1).strip()
        try:
            return json.loads(clean_text)
        except Exception:
            brace_match = re.search(r'\{.*\}', clean_text, re.DOTALL)
            if brace_match:
                try:
                    return json.loads(brace_match.group(0))
                except Exception:
                    pass
        return default_factory()

    def run_map_reduce_synthesis(self, crawl_records, base_domain, model_name=None):
        """
        Executes Phase 1 (Concurrent Map) and Phase 2 (Hierarchical Reduce)
        with strict JSON schemas, grounding rules, concurrency limits (max 10 workers),
        exponential backoff retry for 429 / socket errors, and fallback logic.
        """
        target_model = model_name or getattr(self, 'active_model', 'deepseek-coder:6.7b')
        map_results = []
        if not crawl_records:
            return map_results, {
                "domain_name": base_domain,
                "organization_name": base_domain,
                "primary_purpose": "Web Application",
                "target_audience": ["General Users"],
                "core_offerings": [],
                "domain_structure": "Standard web application structure"
            }

        # [UNICODE:26A1] Active VRAM Shredder & Auto-Scaling for Context Mapping [UNICODE:26A1]
        vram_res = probe_and_scale_vram_resources(target_model)
        map_ctx = vram_res.get("scaled_ctx", 8192)
        map_workers = min(vram_res.get("map_reduce_workers", 2), max(1, len(crawl_records)))
        text_chunk_limit = vram_res.get("text_chunk_len", 4500)
        gpu_base_options = {
            "num_gpu": -1,
            "num_ctx": map_ctx,
            "num_batch": vram_res.get("num_batch", 2048),
            "use_mmap": True,
            "f16_kv": True,
            "num_thread": vram_res.get("num_thread", 4)
        }
        if hasattr(self, 'emit_trace'):
            self.emit_trace(
                "DAEMON_STATUS",
                f"[BRAIN] [CONTEXT MAPPING SCALER] GPU: {vram_res.get('gpu_name')} | "
                f"Free VRAM: {vram_res.get('vram_free_mb')}MB | Context: {map_ctx} tokens | Workers: {map_workers} | Strategy: {vram_res.get('strategy_desc')}"
            )

        # --- Phase 1: The "Map" Prompt (Page-Level Extraction) ---
        map_system_prompt = (
            "You are an expert web data extractor. Your task is to analyze the cleaned text from a single web page and extract its core contextual value.\n\n"
            "RULES:\n"
            "1. Ignore generic UI boilerplate (e.g., 'Log In', 'Privacy Policy', 'Shopping Cart', 'All rights reserved').\n"
            "2. Focus only on substantive content that explains what this page is about.\n"
            "3. Do not hallucinate. If the page lacks substantive content (e.g., an empty login portal), output null values.\n"
            "4. You must only extract entities explicitly mentioned in the text. Cite the URL where the entity was found.\n"
            "5. Extract exactly to the provided JSON schema."
        )

        def extract_single_page_map(record):
            curr_url = record.get("url", "")
            page_title = record.get("title", "")
            page_text = record.get("text", "")
            if not page_text.strip():
                return {
                    "source_url": curr_url,
                    "page_intent": "Empty / No substantive content",
                    "core_entities": [],
                    "page_summary": "Page lacks substantive readable content.",
                    "is_high_value": False
                }

            user_prompt = (
                f"INPUT DATA:\n"
                f"URL: {curr_url}\n"
                f"Page Title: {page_title}\n"
                f"Cleaned Text:\n{page_text[:text_chunk_limit]}\n\n"
                f"JSON Output Schema:\n"
                f"{{\n"
                f'  "page_intent": "string (e.g., \'Product Listing\', \'About Us\', \'Documentation\')",\n'
                f'  "core_entities": ["list of specific products, services, or people mentioned"],\n'
                f'  "page_summary": "string (1-2 sentences summarizing the unique value of this page)",\n'
                f'  "is_high_value": true/false\n'
                f"}}"
            )

            for attempt in range(3):
                try:
                    map_opts = {"temperature": 0.1, "num_predict": 512, **gpu_base_options}
                    res = requests.post(
                        self.ollama_url,
                        json={
                            "model": target_model,
                            "system": map_system_prompt,
                            "prompt": user_prompt,
                            "format": "json",
                            "stream": False,
                            "keep_alive": "60m",
                            "options": map_opts
                        },
                        timeout=45
                    )
                    if res.status_code == 200:
                        raw_resp = res.json().get("response", "")
                        parsed = self.parse_llm_json_response(raw_resp)
                        if isinstance(parsed, dict) and "page_intent" in parsed:
                            parsed["source_url"] = curr_url
                            if "is_high_value" not in parsed:
                                parsed["is_high_value"] = True if len(parsed.get("core_entities", [])) > 0 else False
                            return parsed
                    elif res.status_code == 429:
                        time.sleep(2.0 * (2 ** attempt))
                except Exception:
                    time.sleep(1.0 * (attempt + 1))

            return {
                "source_url": curr_url,
                "page_intent": "General Content",
                "core_entities": record.get("headings", [])[:3],
                "page_summary": page_title,
                "is_high_value": len(page_text) > 300
            }

        max_workers = map_workers
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_rec = {executor.submit(extract_single_page_map, rec): rec for rec in crawl_records}
            for future in as_completed(future_to_rec):
                try:
                    res_map = future.result()
                    if res_map:
                        map_results.append(res_map)
                except Exception:
                    pass

        # --- Phase 2: The "Reduce" Prompt (Domain Synthesis) ---
        high_value_pages = [p for p in map_results if p.get("is_high_value")]
        if not high_value_pages:
            high_value_pages = map_results[:3]

        reduce_system_prompt = (
            f"You are a domain context synthesizer. You are provided with an array of JSON summaries representing the most valuable pages from the domain: {base_domain}.\n\n"
            "Your goal is to aggregate these fragmented page summaries into a single, comprehensive master profile of the entire website and its underlying business or purpose.\n\n"
            "RULES:\n"
            "1. Identify the overarching theme that connects these pages.\n"
            "2. Resolve conflicts. If page summaries contradict each other (e.g., outdated pricing vs. new pricing), note the discrepancy or choose the most frequently cited data.\n"
            "3. Abstract the target audience based on the tone and products offered.\n"
            "4. Output strictly according to the master JSON schema."
        )

        # Hierarchical Reduction Guardrail if page count exceeds single context window limit (> 15 pages)
        summaries_to_reduce = high_value_pages
        if len(high_value_pages) > 15:
            if hasattr(self, 'emit_trace'):
                self.emit_trace("SYSTEM", f"Hierarchical Reduction triggered for {len(high_value_pages)} high-value pages.")
            chunk_size = 8
            intermediate_summaries = []
            chunks = [high_value_pages[i:i + chunk_size] for i in range(0, len(high_value_pages), chunk_size)]
            for c_idx, chunk in enumerate(chunks):
                chunk_prompt = f"Summarize section {c_idx+1} of domain {base_domain}:\n" + json.dumps(chunk, indent=2)
                try:
                    reduce_inter_opts = {"temperature": 0.2, "num_predict": 768, **gpu_base_options}
                    res_c = requests.post(
                        self.ollama_url,
                        json={
                            "model": target_model,
                            "prompt": chunk_prompt,
                            "format": "json",
                            "stream": False,
                            "keep_alive": "60m",
                            "options": reduce_inter_opts
                        },
                        timeout=60
                    )
                    if res_c.status_code == 200:
                        p_chunk = self.parse_llm_json_response(res_c.json().get("response", ""))
                        intermediate_summaries.append(p_chunk)
                except Exception:
                    pass
            if intermediate_summaries:
                summaries_to_reduce = intermediate_summaries

        reduce_input_json = json.dumps(summaries_to_reduce, indent=2)
        reduce_user_prompt = (
            f"INPUT DATA:\n"
            f"{reduce_input_json}\n\n"
            f"JSON Output Schema:\n"
            f"{{\n"
            f'  "domain_name": "{base_domain}",\n'
            f'  "organization_name": "string",\n'
            f'  "primary_purpose": "string (What does this website actually do/sell/provide?)",\n'
            f'  "target_audience": ["list of inferred target demographics or industries"],\n'
            f'  "core_offerings": [\n'
            f'    {{\n'
            f'      "name": "string",\n'
            f'      "description": "string"\n'
            f'    }}\n'
            f'  ],\n'
            f'  "domain_structure": "string (Brief description of how the site is organized)"\n'
            f"}}"
        )

        domain_master_profile = {}
        for attempt in range(3):
            try:
                reduce_final_opts = {"temperature": 0.2, "num_predict": 1024, **gpu_base_options}
                res_red = requests.post(
                    self.ollama_url,
                    json={
                        "model": target_model,
                        "system": reduce_system_prompt,
                        "prompt": reduce_user_prompt,
                        "format": "json",
                        "stream": False,
                        "keep_alive": "60m",
                        "options": reduce_final_opts
                    },
                    timeout=90
                )
                if res_red.status_code == 200:
                    domain_master_profile = self.parse_llm_json_response(res_red.json().get("response", ""))
                    if isinstance(domain_master_profile, dict) and "primary_purpose" in domain_master_profile:
                        break
            except Exception:
                time.sleep(1.5 * (attempt + 1))

        if not domain_master_profile:
            domain_master_profile = {
                "domain_name": base_domain,
                "organization_name": base_domain,
                "primary_purpose": f"Application platform hosted at {base_domain}",
                "target_audience": ["General Users", "Platform Clients"],
                "core_offerings": [{"name": p.get("page_intent", "Service"), "description": p.get("page_summary", "")} for p in high_value_pages[:4]],
                "domain_structure": f"Web portal comprising {len(map_results)} discovered endpoints."
            }

        return map_results, domain_master_profile

    def intelligent_auth_and_spider(self, start_url, username, password, max_depth=2, max_routes=50, coverage_mode="targeted", use_crawl4ai=False, use_visual_scraping=False, use_pyppeteer=False, target_language="en-US", target_region="US", **kwargs):
        start_t = time.time()
        self.log_selenium_action(
            "SESSION_START",
            f"Starting deep DOM spider on {start_url} (Max Depth: {max_depth}, Locale: {target_language}/{target_region})"
        )

        visited = set([start_url])
        queue = []
        discovered_doms = []
        page_manifest = []
        crawl_records = []
        authenticated = False
        
        # Enforce domain boundaries so we don't crawl the whole internet
        base_domain = urlparse(start_url).netloc.replace("www.", "")
        url_signature_counts = {}
        baseline_nav_hashes = set()
        baseline_footer_hashes = set()
        baseline_action_hashes = set()

    # ---------------------------------------------------------
    # 2. NESTED HELPER FUNCTIONS
    # ---------------------------------------------------------
        def get_url_signature(url):
            """Collapses IDs and UUIDs in URLs to group similar pages"""
            parsed = urlparse(url)
            path = re.sub(r'\d+', '*', parsed.path)
            path = re.sub(r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', '*', path)
            return f"{parsed.netloc}{path}"
        
        def interact_with_dynamic_elements():
            """Interacts with tabs, accordions, and dropdowns to expose hidden DOM sections."""
            try:
                expandable = self.driver.find_elements(By.CSS_SELECTOR, "[aria-expanded='false'], .accordion-toggle, .tab-btn, [data-toggle], details:not([open])")
                for el in expandable[:6]:
                    try:
                        if el.is_displayed():
                            self.driver.execute_script("arguments[0].scrollIntoView(true);", el)
                            el.click()
                            time.sleep(0.3)
                    except Exception:
                        continue
            except Exception:
                pass

        # ---------------------------------------------------------
        # Domain Scope Guard & Link Policy Definitions
        # ---------------------------------------------------------
        DISALLOWED_SUBDOMAIN_PREFIXES = {
            'mail', 'email', 'webmail', 'inbox', 'accounts', 'account',
            'login', 'auth', 'sso', 'identity', 'oauth', 'support',
            'help', 'community', 'docs', 'ads', 'ad', 'analytics',
            'tracking', 'pixel', 'policies', 'legal', 'terms', 'privacy',
            'blog', 'news', 'cdn', 'static', 'assets', 'media'
        }

        EXTERNAL_INTEGRATION_MAP = {
            "accounts.google.com": ("OAuth/SSO Identity Provider", "Google Identity Services"),
            "mail.google.com": ("Email Integration Portal", "Google Gmail Webmail"),
            "login.microsoftonline.com": ("OAuth/SSO Identity Provider", "Microsoft Entra / Azure AD"),
            "login.live.com": ("OAuth/SSO Identity Provider", "Microsoft Personal Account"),
            "outlook.live.com": ("Email Integration Portal", "Microsoft Outlook Webmail"),
            "outlook.office365.com": ("Email Integration Portal", "Microsoft Office 365 Webmail"),
            "appleid.apple.com": ("OAuth/SSO Identity Provider", "Apple Sign In"),
            "github.com/login": ("OAuth/SSO Identity Provider", "GitHub OAuth"),
            "auth0.com": ("OAuth/SSO Identity Provider", "Auth0 Universal Login"),
            "okta.com": ("OAuth/SSO Identity Provider", "Okta Identity Cloud"),
            "facebook.com": ("Social / OAuth Integration", "Meta Facebook"),
            "twitter.com": ("Social Integration", "Twitter / X"),
            "x.com": ("Social Integration", "Twitter / X"),
            "linkedin.com": ("Social Integration", "LinkedIn"),
        }

        TRACKING_QUERY_PARAMS = {
            'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
            'sig', 'ved', 'opi', 'usg', 'source', 'sa', 'dsh', 'ec',
            'fbclid', 'gclid', 'msclkid', 'ref', 'source_id', '_ga', '_gl'
        }

        BINARY_EXTENSIONS = (
            '.pdf', '.zip', '.tar', '.gz', '.png', '.jpg', '.jpeg', '.gif',
            '.svg', '.mp4', '.mp3', '.wav', '.exe', '.dmg', '.pkg', '.iso',
            '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx'
        )

        external_integrations = []

        def evaluate_and_clean_url(raw_href, curr_page_url, base_domain):
            if not raw_href or raw_href.startswith(('#', 'javascript:', 'mailto:', 'tel:', 'blob:', 'data:')):
                return ("IGNORE", None, "Non-navigable scheme", None)

            resolved_url = urljoin(curr_page_url, raw_href).split('#')[0]
            parsed = urlparse(resolved_url)

            if parsed.scheme not in ('http', 'https'):
                return ("IGNORE", None, "Unsupported protocol", None)

            if parsed.path.lower().endswith(BINARY_EXTENSIONS):
                return ("IGNORE", None, "Static binary asset", None)

            target_host = parsed.netloc.lower().replace("www.", "")
            clean_base = base_domain.lower().replace("www.", "")

            # Check external integrations first (OAuth, webmail, social)
            for ext_host, (service_type, provider) in EXTERNAL_INTEGRATION_MAP.items():
                if ext_host in target_host or ext_host in parsed.netloc.lower() + parsed.path.lower():
                    return ("EXTERNAL_INTEGRATION", resolved_url, service_type, provider)

            # Check domain boundary
            if target_host == clean_base:
                pass # Exact domain match
            elif target_host.endswith("." + clean_base):
                subdomain_prefix = target_host[:-(len(clean_base) + 1)]
                parts = set(subdomain_prefix.split('.'))
                disallowed_match = parts.intersection(DISALLOWED_SUBDOMAIN_PREFIXES)
                if disallowed_match:
                    return ("DISALLOWED_SUBDOMAIN", resolved_url, f"Excluded service subdomain ({', '.join(disallowed_match)})", subdomain_prefix)
            else:
                return ("OUT_OF_SCOPE", resolved_url, f"Foreign domain ({target_host})", target_host)

            # Clean tracking query params and sort for canonical deduplication
            q_pairs = parse_qsl(parsed.query, keep_blank_values=True)
            filtered_pairs = [
                (k, v) for k, v in q_pairs
                if k.lower() not in TRACKING_QUERY_PARAMS and not k.lower().startswith('utm_')
            ]
            filtered_pairs.sort(key=lambda x: x[0])
            cleaned_query = urlencode(filtered_pairs)
            cleaned_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, cleaned_query, ''))

            return ("IN_SCOPE", cleaned_url, "Valid canonical in-scope URL", None)

        def extract_deep_component_inventory(soup):
            inventory = {
                "select_dropdowns": [],
                "comboboxes": [],
                "radio_groups": {},
                "checkbox_groups": {},
                "standalone_inputs": [],
                "button_variants": [],
                "tab_sets": []
            }

            # 1. SELECT DROPDOWNS
            for sel in soup.find_all("select"):
                sel_id = sel.get("id", "")
                name = sel.get("name", "")
                testid = sel.get("data-testid", "")
                is_multiple = sel.get("multiple") is not None
                is_required = sel.get("required") is not None
                
                label_text = ""
                if sel_id:
                    lbl = soup.find("label", attrs={"for": sel_id})
                    if lbl: label_text = lbl.get_text(strip=True)
                if not label_text:
                    label_text = sel.get("aria-label", "") or name or sel_id or "Dropdown"

                options = []
                for opt in sel.find_all("option"):
                    val = opt.get("value", "")
                    txt = opt.get_text(strip=True) or val
                    is_selected = opt.get("selected") is not None
                    is_disabled = opt.get("disabled") is not None
                    options.append({
                        "value": val,
                        "label": txt,
                        "is_default": is_selected,
                        "is_disabled": is_disabled
                    })
                
                inventory["select_dropdowns"].append({
                    "id": sel_id,
                    "name": name,
                    "data_testid": testid,
                    "label": label_text,
                    "is_multiple": is_multiple,
                    "is_required": is_required,
                    "options_count": len(options),
                    "options": options
                })

            # 2. ARIA COMBOBOXES & LISTBOXES
            for cb in soup.find_all(attrs={"role": re.compile(r"^(combobox|listbox)$")}):
                if cb.name == "select": continue
                cb_id = cb.get("id", "")
                label = cb.get("aria-label", "")
                if not label and cb_id:
                    lbl = soup.find("label", attrs={"for": cb_id})
                    if lbl: label = lbl.get_text(strip=True)
                if not label: label = cb_id or "Custom Select"

                opts = []
                for opt in cb.find_all(attrs={"role": "option"}):
                    opts.append({
                        "value": opt.get("data-value") or opt.get("value") or opt.get_text(strip=True),
                        "label": opt.get_text(strip=True),
                        "is_selected": opt.get("aria-selected") == "true"
                    })
                inventory["comboboxes"].append({
                    "id": cb_id,
                    "label": label,
                    "options": opts
                })

            # 3. RADIO BUTTON GROUPS
            for radio in soup.find_all("input", attrs={"type": "radio"}):
                gname = radio.get("name", "unnamed_radios")
                val = radio.get("value", "")
                rid = radio.get("id", "")
                
                lbl_text = ""
                if rid:
                    lbl = soup.find("label", attrs={"for": rid})
                    if lbl: lbl_text = lbl.get_text(strip=True)
                if not lbl_text and radio.parent and radio.parent.name == "label":
                    lbl_text = radio.parent.get_text(strip=True)
                if not lbl_text: lbl_text = radio.get("aria-label", "") or val

                if gname not in inventory["radio_groups"]:
                    legend_txt = ""
                    fs = radio.find_parent("fieldset")
                    if fs:
                        leg = fs.find("legend")
                        if leg: legend_txt = leg.get_text(strip=True)
                    inventory["radio_groups"][gname] = {
                        "legend": legend_txt or gname,
                        "options": []
                    }

                inventory["radio_groups"][gname]["options"].append({
                    "id": rid,
                    "value": val,
                    "label": lbl_text,
                    "is_checked": radio.get("checked") is not None,
                    "is_disabled": radio.get("disabled") is not None
                })

            # 4. CHECKBOX GROUPS
            for chk in soup.find_all("input", attrs={"type": "checkbox"}):
                cname = chk.get("name", "standalone_checkboxes")
                val = chk.get("value", "true")
                cid = chk.get("id", "")
                
                lbl_text = ""
                if cid:
                    lbl = soup.find("label", attrs={"for": cid})
                    if lbl: lbl_text = lbl.get_text(strip=True)
                if not lbl_text and chk.parent and chk.parent.name == "label":
                    lbl_text = chk.parent.get_text(strip=True)
                if not lbl_text: lbl_text = chk.get("aria-label", "") or cname

                if cname not in inventory["checkbox_groups"]:
                    inventory["checkbox_groups"][cname] = {
                        "options": []
                    }

                inventory["checkbox_groups"][cname]["options"].append({
                    "id": cid,
                    "value": val,
                    "label": lbl_text,
                    "is_checked": chk.get("checked") is not None,
                    "is_disabled": chk.get("disabled") is not None
                })

            # 5. STANDALONE INPUTS & VALIDATION CONSTRAINTS
            for inp in soup.find_all(["input", "textarea"]):
                inp_type = inp.get("type", "text" if inp.name == "input" else "textarea").lower()
                if inp_type in ("radio", "checkbox", "hidden", "submit", "button"): continue
                
                inp_id = inp.get("id", "")
                name = inp.get("name", "")
                testid = inp.get("data-testid", "")
                
                lbl_txt = ""
                if inp_id:
                    lbl = soup.find("label", attrs={"for": inp_id})
                    if lbl: lbl_txt = lbl.get_text(strip=True)
                if not lbl_txt: lbl_txt = inp.get("aria-label", "") or inp.get("placeholder", "") or name
                
                constraints = {}
                if inp.get("required") is not None or inp.get("aria-required") == "true": constraints["required"] = True
                if inp.get("pattern"): constraints["pattern"] = inp.get("pattern")
                if inp.get("min"): constraints["min"] = inp.get("min")
                if inp.get("max"): constraints["max"] = inp.get("max")
                if inp.get("step"): constraints["step"] = inp.get("step")
                if inp.get("minlength"): constraints["minlength"] = inp.get("minlength")
                if inp.get("maxlength"): constraints["maxlength"] = inp.get("maxlength")
                if inp.get("placeholder"): constraints["placeholder"] = inp.get("placeholder")
                if inp.get("autocomplete"): constraints["autocomplete"] = inp.get("autocomplete")
                
                inventory["standalone_inputs"].append({
                    "tag": inp.name,
                    "type": inp_type,
                    "id": inp_id,
                    "name": name,
                    "data_testid": testid,
                    "label": lbl_txt,
                    "value": inp.get("value", ""),
                    "constraints": constraints
                })

            # 6. BUTTON ACTION VARIANTS
            for btn in soup.find_all(["button", "input"]):
                if btn.name == "input" and btn.get("type") not in ("submit", "button"): continue
                btn_txt = (btn.get_text(strip=True) or btn.get("value") or btn.get("title") or btn.get("aria-label") or "Action")[:40]
                btn_id = btn.get("id", "")
                classes = " ".join(btn.get("class", []))
                
                variant = "GENERAL"
                if any(c in classes for c in ["btn-primary", "primary", "bg-blue", "bg-indigo", "bg-emerald"]) or btn.get("type") == "submit":
                    variant = "PRIMARY_CTA"
                elif any(c in classes for c in ["btn-danger", "danger", "destructive", "bg-red", "delete", "remove"]):
                    variant = "DESTRUCTIVE_DANGER"
                elif any(c in classes for c in ["btn-secondary", "secondary", "outline", "border-"]):
                    variant = "SECONDARY_OUTLINE"
                elif btn.get("data-bs-toggle") == "modal" or btn.get("data-modal-target") or btn.get("aria-haspopup") == "dialog":
                    variant = "MODAL_TRIGGER"
                elif btn.get("data-bs-toggle") == "dropdown" or btn.get("aria-haspopup") == "true" or "dropdown-toggle" in classes:
                    variant = "DROPDOWN_TOGGLE"
                    
                target_modal = btn.get("data-bs-target") or btn.get("data-modal-target") or ""
                is_disabled = btn.get("disabled") is not None or btn.get("aria-disabled") == "true"
                
                inventory["button_variants"].append({
                    "text": btn_txt,
                    "id": btn_id,
                    "variant": variant,
                    "target_modal": target_modal,
                    "is_disabled": is_disabled,
                    "classes": classes
                })

            # 7. TAB SETS
            for tablist in soup.find_all(attrs={"role": "tablist"}):
                tabs = []
                for t in tablist.find_all(attrs={"role": "tab"}):
                    tabs.append({
                        "id": t.get("id", ""),
                        "label": t.get_text(strip=True),
                        "is_active": t.get("aria-selected") == "true",
                        "controls": t.get("aria-controls", "")
                    })
                if tabs:
                    inventory["tab_sets"].append({
                        "id": tablist.get("id", ""),
                        "tabs": tabs
                    })

            # Format Markdown
            md = "\n**[DEEP COMPONENT INVENTORY & OPTION MATRIX]**\n"
            
            if inventory["select_dropdowns"]:
                md += f"#### [UNICODE:1F53D] Dropdown Selectors ({len(inventory['select_dropdowns'])} components):\n"
                for s in inventory["select_dropdowns"]:
                    mult_flag = " [MULTI-SELECT]" if s["is_multiple"] else ""
                    req_flag = " [REQUIRED]" if s["is_required"] else ""
                    md += f"- Select `#{s['id'] or s['name']}` (Label: '{s['label']}'){mult_flag}{req_flag}:\n"
                    md += f"  Options ({s['options_count']} choices):\n"
                    for opt in s["options"]:
                        def_mark = " (DEFAULT)" if opt["is_default"] else ""
                        dis_mark = " (DISABLED)" if opt["is_disabled"] else ""
                        check_box = "[[UNICODE:2713]]" if opt["is_default"] else "[ ]"
                        md += f"    {check_box} '{opt['value']}' -> \"{opt['label']}\"{def_mark}{dis_mark}\n"

            if inventory["comboboxes"]:
                md += f"#### [UNICODE:1F5C2] Custom ARIA Comboboxes ({len(inventory['comboboxes'])} components):\n"
                for cb in inventory["comboboxes"]:
                    md += f"- Combobox `#{cb['id']}` (Label: '{cb['label']}'):\n"
                    for opt in cb["options"]:
                        check_box = "[[UNICODE:2713]]" if opt["is_selected"] else "[ ]"
                        md += f"    {check_box} '{opt['value']}' -> \"{opt['label']}\"\n"

            if inventory["radio_groups"]:
                md += f"#### [UNICODE:1F518] Radio Button Groups ({len(inventory['radio_groups'])} groups):\n"
                for gname, gdata in inventory["radio_groups"].items():
                    md += f"- Radio Group [{gname}] (Legend: '{gdata['legend']}'):\n"
                    for opt in gdata["options"]:
                        check_mark = "([BULLET])" if opt["is_checked"] else "( )"
                        def_mark = " (DEFAULT)" if opt["is_checked"] else ""
                        dis_mark = " (DISABLED)" if opt["is_disabled"] else ""
                        md += f"    {check_mark} '{opt['value']}' -> \"{opt['label']}\"{def_mark}{dis_mark}\n"

            if inventory["checkbox_groups"]:
                md += f"#### [UNICODE:2611] Checkbox Groups & Options ({len(inventory['checkbox_groups'])} groups):\n"
                for gname, gdata in inventory["checkbox_groups"].items():
                    md += f"- Checkbox Group [{gname}]:\n"
                    for opt in gdata["options"]:
                        check_box = "[[UNICODE:2713]]" if opt["is_checked"] else "[ ]"
                        dis_mark = " (DISABLED)" if opt["is_disabled"] else ""
                        md += f"    {check_box} '{opt['value']}' -> \"{opt['label']}\"{dis_mark}\n"

            if inventory["standalone_inputs"]:
                md += f"#### [UNICODE:1F4DD] Form Inputs & Validation Constraints ({len(inventory['standalone_inputs'])} fields):\n"
                for inp in inventory["standalone_inputs"]:
                    c_strs = [f"{k}: '{v}'" for k, v in inp["constraints"].items()]
                    c_formatted = f" | Constraints: [{', '.join(c_strs)}]" if c_strs else ""
                    md += f"- Input `#{inp['id'] or inp['name']}` | Type: '{inp['type']}' | Label: '{inp['label']}'{c_formatted}\n"

            if inventory["button_variants"]:
                md += f"#### [UNICODE:1F3AF] Button Action Variants ({len(inventory['button_variants'])} buttons):\n"
                for b in inventory["button_variants"]:
                    modal_info = f" -> Opens Modal: `{b['target_modal']}`" if b["target_modal"] else ""
                    state_info = " (DISABLED)" if b["is_disabled"] else ""
                    md += f"- [{b['variant']}] \"{b['text']}\" | Id: `#{b['id']}`{modal_info}{state_info}\n"

            if inventory["tab_sets"]:
                md += f"#### [BOOK] Tab Sets & Views ({len(inventory['tab_sets'])} sets):\n"
                for ts in inventory["tab_sets"]:
                    md += f"- Tab Set `#{ts['id']}`:\n"
                    for t in ts["tabs"]:
                        active_mark = " (ACTIVE)" if t["is_active"] else ""
                        md += f"    * Tab: \"{t['label']}\" | Controls: `{t['controls']}`{active_mark}\n"

            return md, inventory

        # ---------------------------------------------------------
        # Helper: Extract Clean DOM Blueprint & Discover Internal Links
        # ---------------------------------------------------------
        def extract_dom_and_queue(html_source, curr_url, depth, is_baseline=False):
            soup = BeautifulSoup(html_source, "html.parser")

            # Simple NLP Taxonomy Bag of Words
            text_lower = soup.get_text(separator=" ", strip=True).lower()
            taxonomy_tag = "GENERAL_CONTENT"
            if any(w in text_lower for w in ["login", "sign in", "password", "authenticate"]): taxonomy_tag = "AUTH"
            elif any(w in text_lower for w in ["checkout", "cart", "buy", "purchase", "billing"]): taxonomy_tag = "CHECKOUT"
            elif any(w in text_lower for w in ["dashboard", "overview", "analytics", "metrics"]): taxonomy_tag = "DASHBOARD"
            elif any(w in text_lower for w in ["settings", "profile", "account", "preferences"]): taxonomy_tag = "SETTINGS"
            
            # Extract Meta Business Context & Title first
            meta_desc = ""
            meta_title = ""
            for meta in soup.find_all("meta"):
                name = meta.get("name", "").lower()
                prop = meta.get("property", "").lower()
                if name == "description" or prop == "og:description":
                    meta_desc = meta.get("content", "").strip()
                if prop == "og:title":
                    meta_title = meta.get("content", "").strip()

            page_title = soup.title.get_text(strip=True) if soup.title else "No Title"
            if meta_title and page_title == "No Title": page_title = meta_title

            # Extract Headings (H1, H2, H3)
            headings = []
            for h in soup.find_all(["h1", "h2", "h3"]):
                text = h.get_text(separator=" ", strip=True)
                if text and text not in headings:
                    headings.append(f"{h.name.upper()}: {text}")
                    if len(headings) >= 6: break
            
            # Extract Substantive Body Text with Boilerplate Stripping (prevents Footer / Privacy contamination)
            cleaned_page_text = self.clean_page_text_for_extraction(html_source)
            body_snippet = cleaned_page_text[:2500] + "..." if len(cleaned_page_text) > 2500 else cleaned_page_text

            crawl_records.append({
                "url": curr_url,
                "title": page_title,
                "text": cleaned_page_text,
                "meta_desc": meta_desc,
                "headings": headings
            })

            if coverage_mode == "exhaustive":
                for tag in soup(["script", "style", "noscript", "iframe"]):
                    tag.decompose()
            else:
                for tag in soup(["script", "style", "noscript", "meta", "svg", "path", "iframe"]):
                    tag.decompose()
            
            html_lang = soup.html.get("lang", "unknown") if soup.html else "unknown"
            
            # Detect Language Switchers
            lang_options = []
            for select in soup.find_all("select"):
                if "lang" in select.get("name", "").lower() or "lang" in select.get("id", "").lower():
                    for opt in select.find_all("option"):
                        lang_options.append(opt.get_text(strip=True))
            for a in soup.find_all("a"):
                if a.get("hreflang") or "lang=" in a.get("href", "") or a.get("data-lang"):
                    lang_options.append(a.get_text(strip=True) or a.get("hreflang", ""))
                    
            i18n_flag = f" [I18N_DETECTED: {', '.join(set(lang_options[:5]))}]" if lang_options else ""
            
            dom_summary = f"### [UNICODE:1F30D] PAGE ROUTE: {curr_url}\n**Page Title:** {page_title}\n**Taxonomy:** [{taxonomy_tag}]\n**HTML Lang:** {html_lang}{i18n_flag}\n"
            if meta_desc: dom_summary += f"**Meta Description:** {meta_desc}\n"
            dom_summary += "\n**[BUSINESS CONTEXT - HEADINGS]**\n"
            if headings:
                dom_summary += "\n".join([f"- {h}" for h in headings]) + "\n"
            else:
                dom_summary += "- (No semantic headings found)\n"
            dom_summary += "\n**[BUSINESS CONTEXT - BODY SNIPPET]**\n"
            dom_summary += f"> {body_snippet or '(No meaningful text paragraphs found)'}\n\n"
            
            inputs_found = 0
            buttons_found_set = set()
            links_found_count = 0

            # 1. Structural Scopes: Header & Navigation
            header = soup.find(["header", "nav"]) or soup.find(id=re.compile(r"header|nav", re.I))
            if header:
                dom_summary += "**[HEADER & GLOBAL NAVIGATION]**\n"
                nav_links = header.find_all("a", href=True)
                for nl in nav_links[:10]:
                    txt = nl.get_text(strip=True) or "Nav Item"
                    href = nl.get('href')
                    sig = f"{txt}_{href}"
                    if is_baseline: baseline_nav_hashes.add(sig)
                    elif sig in baseline_nav_hashes: continue
                    dom_summary += f"  > Nav Action: '{txt}' | Href: `{href}` | Id: `{nl.get('id', 'none')}`\n"
                dom_summary += "\n"

            # 2. Forms & Data Entry
            forms = soup.find_all("form")
            dom_summary += "**[FORMS & DATA ENTRY]**\n"
            
            def is_input(tag):
                return tag.name in ["input", "textarea", "select"] or tag.get("role") in ["textbox", "search", "combobox", "spinbutton"]
                
            def is_action(tag):
                return (
                    tag.name in ["button", "a"] or 
                    tag.get("role") in ["button", "link", "menuitem", "option", "tab", "treeitem", "switch"] or
                    tag.get("onclick") is not None or
                    (tag.name in ["li", "div", "span"] and tag.get("data-testid") is not None)
                )

            if forms:
                for idx, form in enumerate(forms):
                    action = form.get("action", "none")
                    form_id = form.get("id", "none")
                    dom_summary += f"- Form {idx+1} (Action: '{action}', ID: '{form_id}'):\n"
                    for i in form.find_all(is_input):
                        if i.get("type") == "hidden": continue
                        ident = i.get("data-testid") or i.get("id") or i.get("name") or i.get("placeholder") or i.get("aria-label") or "unknown"
                        wdio_hint = f"$('[data-testid=\"{i.get('data-testid')}\"]')" if i.get("data-testid") else (f"$('#{i.get('id')}')" if i.get("id") else "")
                        type_hint = i.get("type") or i.get("role") or "text"
                        dom_summary += f"  > Input [{i.name}] | Type: '{type_hint}' | Locator: `{ident}` | WDIO: `{wdio_hint}`\n"
                        inputs_found += 1
                    for b in form.find_all(["button", "input"]):
                        if b.name == "input" and b.get("type") not in ("submit", "button"): continue
                        text = (b.text.strip() or b.get("value", "") or b.get("aria-label") or "Submit")[:30]
                        ident = b.get("data-testid") or b.get("id") or "unknown"
                        dom_summary += f"  > Form Submit Action | Text: '{text}' | Locator: `{ident}`\n"
                        buttons_found_set.add(text)
            else:
                for i in soup.find_all(is_input):
                    if i.get("type") == "hidden": continue
                    ident = i.get("data-testid") or i.get("id") or i.get("name") or i.get("placeholder") or i.get("aria-label") or "unknown"
                    type_hint = i.get("type") or i.get("role") or "text"
                    dom_summary += f"- Standalone Input [{i.name}] | Type: '{type_hint}' | Locator: `{ident}`\n"
                    inputs_found += 1

            if inputs_found == 0: dom_summary += "- No data entry fields found.\n"

            # 3. Global Actions & Buttons
            dom_summary += "\n**[INTERACTIVE BUTTONS & ACTIONS]**\n"
            action_groups = {}
            for el in soup.find_all(is_action):
                raw_text = el.text.strip() or el.get("title") or el.get("aria-label") or el.get("value") or ""
                text = " ".join(raw_text.split())[:40]
                if not text: text = f"Action_{el.name}_{el.get('role', 'btn')}"
                href = el.get("href", "")
                ident = el.get("data-testid") or el.get("id") or el.get("name") or "unknown"
                
                if text not in action_groups:
                    action_groups[text] = {"count": 0, "locators": set(), "hrefs": set()}
                action_groups[text]["count"] += 1
                if ident != "unknown" and len(action_groups[text]["locators"]) < 2:
                    action_groups[text]["locators"].add(ident)
                if href and not href.startswith(('#', 'javascript:', 'mailto:', 'tel:')) and len(action_groups[text]["hrefs"]) < 2:
                    action_groups[text]["hrefs"].add(href)
                    links_found_count += 1

            sorted_groups = sorted(action_groups.items(), key=lambda x: (x[0].startswith("Action_"), -x[1]["count"]))
            for text, data in sorted_groups[:100]:
                loc_str = f"`{list(data['locators'])[0]}`" if data["locators"] else "`unknown`"
                href_str = f"`{list(data['hrefs'])[0]}`" if data["hrefs"] else "`none`"
                sig = f"{text}_{href_str}"
                if is_baseline: baseline_action_hashes.add(sig)
                elif sig in baseline_action_hashes: continue
                dom_summary += f"- Action: '{text}' | Loc: {loc_str} | Href: {href_str}\n"
            dom_summary += "\n"

            # 4. Footer Structure
            footer = soup.find(["footer"]) or soup.find(id=re.compile(r"footer", re.I))
            if footer:
                dom_summary += "**[FOOTER & COMPLIANCE]**\n"
                for fl in footer.find_all("a", href=True)[:6]:
                    txt = fl.get_text(strip=True)
                    href = fl.get('href')
                    sig = f"{txt}_{href}"
                    if is_baseline: baseline_footer_hashes.add(sig)
                    elif sig in baseline_footer_hashes: continue
                    dom_summary += f"  > Footer Link: '{txt}' | Href: `{href}`\n"
                dom_summary += "\n"

            # 5. Extract Deep Component Inventory & Option Matrix
            deep_component_md, component_inventory = extract_deep_component_inventory(soup)
            dom_summary += deep_component_md

            # 6. Index into DOMVectorEngine
            if hasattr(self, 'vector_dom_engine') and self.vector_dom_engine:
                try:
                    self.vector_dom_engine.index_page_dom(html_source, curr_url, driver=self.driver)
                except Exception:
                    pass

            # 7. Queue Sub-routes with Domain & Scope Protection
            queued_this_page = 0
            if depth < max_depth:
                for a in soup.find_all("a", href=True):
                    href = a.get("href", "").strip()
                    status, clean_url, reason, meta = evaluate_and_clean_url(href, curr_url, base_domain)
                    if status == "EXTERNAL_INTEGRATION":
                        ext_rec = {
                            "type": reason,
                            "provider": meta,
                            "url": clean_url,
                            "discovered_on": curr_url
                        }
                        if not any(e.get("url") == clean_url for e in external_integrations):
                            external_integrations.append(ext_rec)
                            self.log_selenium_action("LINK_SCOPE_GUARD", f"Isolated external integration ({meta}) from crawl queue; recorded as integration boundary: {clean_url}")
                    elif status == "IN_SCOPE" and clean_url not in visited:
                        sig = get_url_signature(clean_url)
                        if url_signature_counts.get(sig, 0) < 4:
                            url_signature_counts[sig] = url_signature_counts.get(sig, 0) + 1
                            queue.append((clean_url, depth + 1))
                            visited.add(clean_url)
                            queued_this_page += 1
                            self.log_selenium_action("DISCOVER_LINK", f"Queued in-scope sub-route: {clean_url}")
                    elif status in ("DISALLOWED_SUBDOMAIN", "OUT_OF_SCOPE"):
                        pass

            if use_crawl4ai:
                try:
                    import asyncio
                    from crawl4ai import AsyncWebCrawler
                    async def fetch_c4ai():
                        async with AsyncWebCrawler() as crawler:
                            res = await crawler.arun(url=curr_url)
                            return res.markdown
                    
                    new_loop = asyncio.new_event_loop()
                    c4ai_md = new_loop.run_until_complete(fetch_c4ai())
                    new_loop.close()
                    dom_summary += f"\n\n**[CRAWL4AI DEEP SEMANTIC MARKDOWN]**\n{c4ai_md}\n"
                except ImportError:
                    self.log_selenium_action("CRAWL4AI_ERROR", "crawl4ai is not installed.")
                except Exception as e:
                    self.log_selenium_action("CRAWL4AI_ERROR", f"Crawl4AI exception: {e}")

            discovered_doms.append(dom_summary)
            page_manifest.append({
                "url": curr_url, "inputs": inputs_found, "unique_buttons": len(sorted_groups),
                "total_links": links_found_count, "tables": len(soup.find_all("table")), "dom_snippet": dom_summary,
                "component_inventory": component_inventory,
            })
            self.log_selenium_action("DOM_EXTRACT", f"Indexed {curr_url} with deep component matrix. Queued {queued_this_page} in-scope routes.")

        try:
            cmd_nav = f"driver.get('{start_url}')"
            if hasattr(self, 'update_pipeline_state'):
                self.update_pipeline_state(current_task=f"Spidering Base Route: {start_url}", current_command=cmd_nav)
                
            self.log_selenium_action("NAVIGATE", f"WebDriver navigating to root: {start_url}")
            self.driver.get(start_url)
            self.wait_for_page_ready(timeout=25)
            
            try: 
                interact_with_dynamic_elements()
            except Exception: pass
            
            if hasattr(self, 'capture_frame'):
                self.capture_frame(f"View @ {start_url}")
                
            if username and password:
                user_fields = self.driver.find_elements(By.CSS_SELECTOR, "input[type='text'], input[type='email'], input[name*='user'], input[name*='email'], input[id*='user']")
                pass_fields = self.driver.find_elements(By.CSS_SELECTOR, "input[type='password']")
                if user_fields and pass_fields:
                    user_fields[0].clear(); user_fields[0].send_keys(username)
                    pass_fields[0].clear(); pass_fields[0].send_keys(password)
                    submit_buttons = self.driver.find_elements(By.CSS_SELECTOR, "button[type='submit'], input[type='submit'], button")
                    if submit_buttons:
                        submit_buttons[0].click()
                        self.wait_for_page_ready(timeout=25)
                        
                        page_text = self.driver.page_source.lower()
                        if "invalid" not in page_text and "error" not in page_text:
                            authenticated = True
                            if hasattr(self, 'capture_frame'):
                                self.capture_frame("Authenticated Dashboard")

            extract_dom_and_queue(self.driver.page_source, self.driver.current_url, depth=0, is_baseline=True)

            pages_crawled = 1
            self.log_selenium_action("DEEP_CRAWL", f"Starting deep crawl via WebDriver. Current queue size: {len(queue)}")
            
            while queue and pages_crawled < max_routes:
                curr_url, depth = queue.pop(0)
                try:
                    if hasattr(self, 'update_pipeline_state'):
                        self.update_pipeline_state(current_task=f"Crawling Depth {depth}: {curr_url}", current_command=f"driver.get('{curr_url}')")
                        
                    self.log_selenium_action("NAVIGATE", f"Crawling depth {depth}: {curr_url}")
                    self.driver.get(curr_url)
                    self.wait_for_page_ready(timeout=20)
                    
                    try: 
                        interact_with_dynamic_elements()
                    except Exception: pass
                    
                    if hasattr(self, 'capture_frame'):
                        self.capture_frame(f"View @ Depth {depth}")
                    
                    extract_dom_and_queue(self.driver.page_source, curr_url, depth)
                    pages_crawled += 1
                    
                except Exception as e:
                    self.log_selenium_action("CRAWL_ERROR", f"Failed to load {curr_url}: {str(e)}")

        except Exception as e:
            self.log_selenium_action("FATAL_ERROR", f"Crawler engine crashed: {str(e)}")

        # ---------------------------------------------------------
        # [UNICODE:26A1] Run Map-Reduce Page-Level Extraction & Domain Synthesis [UNICODE:26A1]
        # ---------------------------------------------------------
        try:
            self.log_selenium_action("MAP_REDUCE", f"Executing concurrent Map extraction across {len(crawl_records)} valid URLs...")
            map_results, domain_profile = self.run_map_reduce_synthesis(crawl_records, base_domain)
            self.domain_master_profile = domain_profile
            
            map_by_url = {m.get("source_url"): m for m in map_results if m.get("source_url")}
            for idx, pm in enumerate(page_manifest):
                u = pm.get("url")
                m_info = map_by_url.get(u, {})
                pm["page_intent"] = m_info.get("page_intent", "General")
                pm["core_entities"] = m_info.get("core_entities", [])
                pm["page_summary"] = m_info.get("page_summary", "")
                pm["is_high_value"] = m_info.get("is_high_value", False)
                
                if m_info and idx < len(discovered_doms):
                    ai_block = (
                        f"\n**[AI MAP SYNTHESIS]**\n"
                        f"- Page Intent: {m_info.get('page_intent', 'General')}\n"
                        f"- High-Value Route: {m_info.get('is_high_value', False)}\n"
                        f"- Core Entities: {', '.join(m_info.get('core_entities', []))}\n"
                        f"- Page Summary: {m_info.get('page_summary', 'N/A')}\n"
                    )
                    discovered_doms[idx] += ai_block
            self.log_selenium_action("MAP_REDUCE_DONE", f"Synthesized Domain Master Profile for '{base_domain}': {domain_profile.get('primary_purpose', 'Completed')}")
        except Exception as mr_err:
            self.log_selenium_action("MAP_REDUCE_WARN", f"Map-Reduce synthesis warning: {mr_err}")
            self.domain_master_profile = {}

        self.external_integrations = external_integrations
        if hasattr(self, 'domain_master_profile') and isinstance(self.domain_master_profile, dict):
            self.domain_master_profile["external_integrations"] = external_integrations

        elapsed = round(time.time() - start_t, 2)
        self.log_selenium_action("SESSION_END", f"DOM traversal completed in {elapsed}s. Indexed: {len(discovered_doms)} views ({len(external_integrations)} external integrations isolated).")
        return discovered_doms, page_manifest, authenticated

    def run_contextual_analysis(self, url, detected_stack, combined_dom, apis, model_name, ctx_size, strategy, temperature, max_tokens, pipeline_steps, selected_language="Python", selected_framework="Robot Framework + Pytest", sdet_philosophy="Behavior-Driven Development (BDD)", coverage_mode="targeted"):
        pipeline_steps["step_2_5"]["status"] = "RUNNING"
        self.update_pipeline_state(status="running", progress=45, steps=pipeline_steps, current_task=f"BRD Synthesis & Architecture Audit ({model_name})", current_command="Synthesizing BRD Draft...", chunking=False)
        
        # [UNICODE:26A1] Dynamic Context & VRAM Resource Sizing [UNICODE:26A1]
        vram_res = probe_and_scale_vram_resources(model_name, requested_ctx=ctx_size)
        safe_ctx = vram_res.get("scaled_ctx", 8192)
        max_dom_chars = min(35000, int(safe_ctx * 2.5))
        dom_context = combined_dom[:max_dom_chars] + "\n...[DOM Truncated for Context Limits]" if len(combined_dom) > max_dom_chars else combined_dom
        
        api_str = json.dumps(apis, indent=2)
        api_context = api_str[:4000] + "\n...[API Truncated]" if len(api_str) > 4000 else api_str

