            max_tokens=cfg_dict.get('max_tokens', 4096),
            execution_mode=cfg_dict.get('execution_mode', 'auto'), 
            selected_urls=cfg_dict.get('selected_urls', None),
            custom_prompts=cfg_dict.get('custom_prompts', None), 
            sdet_philosophy=cfg_dict.get('sdet_philosophy', 'Behavior-Driven Development (BDD)'),
            selected_language=cfg_dict.get('selected_language', 'Python'), 
            selected_framework=cfg_dict.get('selected_framework', 'Robot Framework + Pytest'),
