import threading

class CalibrationPayload(BaseModel):
    model: str = "deepseek-r1:1.5b"

@app.post("/api/system/calibrate/start")
def start_calibration(payload: CalibrationPayload):
    if stress_tester_instance.is_running:
        return {"status": "already_running"}
    stress_tester_instance.model = payload.model
    t = threading.Thread(target=stress_tester_instance.run_stress_test)
    t.start()
    return {"status": "started"}

@app.get("/api/system/calibrate/status")
def get_calibration_status():
    import redis, os
    r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
    return {
        "status": (r.get("calibration_status") or b"IDLE").decode("utf-8"),
        "current_thread": int(r.get("calibration_current_thread") or 0),
        "last_vram": int(r.get("calibration_last_vram") or 0),
        "last_time": float(r.get("calibration_last_time") or 0.0),
        "optimal": int(r.get("calibration_optimal") or 1)
    }

class ConcurrencyPayload(BaseModel):
    concurrency: int

@app.post("/api/system/concurrency")
def update_concurrency(payload: ConcurrencyPayload):
    try:
        req_conc = payload.concurrency
        telemetry = get_system_and_gpu_telemetry()
        vram_avail_gb = 0.0
        
        if telemetry["gpu"]["status"] != "CPU_BOUND":
            vram_total_gb = telemetry["gpu"]["vram_total"] / 1024
        else:
            vram_total_gb = telemetry["system"]["ram_total_gb"]
            
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        safe_conc = min(max(1, int(vram_total_gb / 1.5)), 8)
        try:
            calibrated = int(r.get("calibration_optimal") or 0)
            safe_conc = max(safe_conc, calibrated)
        except: pass
        
        is_capped = False
        final_conc = req_conc
        msg = "Concurrency updated successfully."
        
        if req_conc > safe_conc:
            is_capped = True
            final_conc = safe_conc
            msg = f"Resource Shield Active: Requested {req_conc} threads exceeds safe hardware limit. Capped at {safe_conc}."
            
        r.set("mcp_global_concurrency", final_conc)
        return {"status": "success", "concurrency": final_conc, "capped": is_capped, "message": msg}
    except Exception as e:
        return {"status": "error", "message": str(e)}

