@app.post("/api/prompts/generate")
def generate_prompt(payload: PromptGenPayload):
    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate")
    sys_prompt = f"You are a Senior QA Test Architect. The user wants to write a test script for {payload.vector}. Expand the following short intent into a comprehensive, highly-detailed LLM prompt instruction for writing robust test automation scripts. Return ONLY the final expanded prompt text. Do not include markdown code block formatting or conversational text.\nIntent: {payload.intent}"
    try:
        res = requests.post(ollama_url, json={"model": payload.model_name, "prompt": sys_prompt, "stream": False, "options": {"temperature": 0.0, "top_p": 0.1, "top_k": 10, "repeat_penalty": 1.0, "num_gpu": -1}}, timeout=45)
        res_data = res.json()
        try:
            
            eval_count = res_data.get("eval_count", 0)
            prompt_eval_count = res_data.get("prompt_eval_count", 0)
            if eval_count > 0 or prompt_eval_count > 0: update_and_get_tokens(eval_count, prompt_eval_count)
        except: pass
        return {"status": "success", "generated_prompt": res_data.get("response", "").strip()}
    except Exception as e:
        return {"status": "error", "message": str(e)}

