@app.post("/api/crawl")
async def trigger_crawl(payload: Dict[str, Any]):
    """
    Dispatches headless spider.
    Body: {"url": "...", "depth": 2, "auth": {...}}
    Consumer: React Dashboard / CI Webhook
    """
    try:
        url = payload.get("url", "")
        depth = payload.get("depth", 2)
        auth = payload.get("auth", {})
        
        if not url:
            return JSONResponse(status_code=400, content={"status": "error", "message": "URL is required in payload."})
        
        def run_crawl():
            try:
                engine = AICoreEngine(None, os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"))
                username = auth.get("username", "")
                password = auth.get("password", "")
                engine.intelligent_auth_and_spider(
                    start_url=url,
                    username=username,
                    password=password,
                    max_depth=depth,
                    coverage_mode="targeted"
                )
                session_data = {
                    "url": url,
                    "depth": depth,
                    "auth": auth,
                    "status": "completed",
                    "timestamp": time.strftime("%Y-%m-%d %H:%M:%S")
                }
                with open("artifacts/logs/pipeline_session.json", "w", encoding="utf-8") as f:
                    json.dump(session_data, f, indent=2)
            except Exception as e:
                with open("artifacts/logs/pipeline_session.json", "w", encoding="utf-8") as f:
                    json.dump({"url": url, "status": "error", "message": str(e)}, f, indent=2)
        
        in_process_pool.submit(run_crawl)
        return {"status": "success", "message": f"Crawl dispatched for {url} with depth {depth}"}
    except Exception as e:
        return JSONResponse(status_code=500, content={"status": "error", "message": str(e)})

@app.get("/api/scope_gate/status")
def get_scope_gate_status():
    """
    Queries discovered routes, token burn estimates, and risk profile.
    Consumer: Scope Gate HITL Modal
    """
    try:
        page_manifest_file = "artifacts/reports/page_manifest.json"
        
        page_manifest = []
        if os.path.exists(page_manifest_file):
            try:
                with open(page_manifest_file, "r", encoding="utf-8") as f:
                    page_manifest = json.load(f)
            except:
                pass
        
        route_count = len(page_manifest) if page_manifest else 0
        estimated_tokens = route_count * 5000
        
        risk_profile = "LOW"
        if route_count > 50:
            risk_profile = "HIGH"
        elif route_count > 20:
            risk_profile = "MEDIUM"
        
        return {
            "discovered_routes": page_manifest,
            "route_count": route_count,
            "token_burn_estimate": estimated_tokens,
            "risk_profile": risk_profile,
            "status": "ready_for_review"
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

