@app.post("/api/generate")
def trigger_generation(cfg: GenConfig):
    global active_harness
    if active_harness:
        try: active_harness.stop()
        except: pass
        import time; time.sleep(1)
    nuke_all_resources()

    # Sync requested concurrency directly to Redis for active session
    try:
        import redis as py_redis
        r_sync = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r_sync.set("mcp_global_concurrency", cfg.mcp_concurrency)
    except Exception:
        pass

    # Create the enhanced MCP harness and store globally for stop control
    active_harness = EnhancedMCPHarness(
        ollama_url=os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"),
        model_name=cfg.model_name,
        status_callback=lambda msg: print(msg),
        trace_callback=lambda *a: None,
        ctx_size=cfg.context_size,
        strategy=cfg.compute_strategy,
        concurrency=cfg.mcp_concurrency,
        temperature=cfg.temperature,
        max_tokens=cfg.max_tokens,
        chunk_threshold=int(cfg.context_size * 0.5)
    )

    for folder in ["artifacts/logs", "artifacts/scripts", "artifacts/screencast"]:
        shutil.rmtree(folder, ignore_errors=True)
        os.makedirs(folder, exist_ok=True)
        
    # Carefully clean reports without destroying historical archives
    os.makedirs("artifacts/reports", exist_ok=True)
    for sub in ["allure-results"]: # Leave allure-report intact so trends survive
        shutil.rmtree(f"artifacts/reports/{sub}", ignore_errors=True)
    
    with open("artifacts/logs/orchestrator.log", "w", encoding="utf-8") as f: 
        f.write("=== [ORCHESTRATOR STARTED] Master Session Initialized ===\n")
        f.flush()
        
    init_entry = {
        "time": datetime.now().strftime("%H:%M:%S.%f")[:-3],
        "cat": "DAEMON_STATUS",
        "msg": f"Target initiated: {cfg.url} [Mode: {cfg.execution_mode.upper()}], Model: {cfg.model_name}, Stack: {cfg.selected_stack}, Workers: {cfg.mcp_concurrency}",
        "elapsed": 0, "inference": 0, "tokens": 0, "speed": 0
    }
    with open("artifacts/logs/engine_trace.jsonl", "w", encoding="utf-8") as f:
        f.write(json.dumps(init_entry) + "\n")
        f.flush()
    
    init_steps = {
        "step_1": {"name": "1. Recon & CVE", "status": "PENDING", "required": True},
        "step_2": {"name": "2. Auth & Spider", "status": "PENDING", "required": True},
        "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
        "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
        "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
        "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
    }
    
    import time
    with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f:
        json.dump({
            "status": "processing", 
            "progress": 5, 
            "steps": init_steps, 
            "current_task": f"Initializing Engine in {cfg.execution_mode.upper()} Mode", 
            "current_command": "Spawning Celery process...", 
            "chunking": False,
            "start_time": time.time()
        }, f)
    
    # 1. Safely extract the dictionary supporting both Pydantic V1 and V2
    try:
        cfg_data = cfg.model_dump()
    except AttributeError:
        cfg_data = cfg.dict()

    # 2. Attempt Celery dispatch, fallback to in-process ThreadPool if Celery is offline
    try:
        generate_artifacts_task.delay(cfg_data)
    except Exception as e:
        print(f"[WARNING] Celery dispatch failed ({e}). Falling back to in-process execution.")
        in_process_pool.submit(run_e2e_pipeline_core, cfg_data)
        
    return {"status": "processing"}

@app.post("/api/pipeline/resume")
def resume_pipeline(payload: ResumePayload):
    global active_harness
    if active_harness:
        try: active_harness.stop()
        except: pass
        import time; time.sleep(1)
        
    try:
        path = "artifacts/logs/engine_trace.jsonl"
        if os.path.exists(path):
            open(path, "w", encoding="utf-8").close()
    except: pass

    try:
        import redis as py_redis
        r_sync = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r_sync.set("mcp_global_concurrency", payload.mcp_concurrency)
    except Exception:
        pass
    
    def resume_task_worker():
        try:
            with open("artifacts/logs/pipeline_session.json", "r", encoding="utf-8") as f:
                sess = json.load(f)
            
            with open("artifacts/logs/task_status.json", "r", encoding="utf-8") as f:
                curr_state = json.load(f)
            
            steps = curr_state.get("steps", {
                "step_1": {"name": "1. Recon & CVE", "status": "COMPLETED", "required": True},
                "step_2": {"name": "2. Auth & Spider", "status": "COMPLETED", "required": True},
                "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
                "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
                "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
                "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
            })
            
            engine = AICoreEngine(None, os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"))
            dom_pages = sess.get("dom_pages", [])
            
            if payload.override_token_check:
                filtered_doms = dom_pages
            else:
                filtered_doms = [d for d in dom_pages if any(u in d for u in payload.selected_urls)] if payload.selected_urls else dom_pages
            if not filtered_doms: filtered_doms = dom_pages
            
            max_dom_chars = int(payload.context_size * 2.2)
            combined_dom = "\n\n".join(filtered_doms) if payload.coverage_mode == "exhaustive" else "\n\n".join(filtered_doms)[:max_dom_chars]
            
            engine.emit_trace("DAEMON_STATUS", f"[UNICODE:1F9ED] Resuming pipeline with {len(filtered_doms)} page scopes. Override All: {payload.override_token_check}")
            
            contextual_analysis = engine.run_contextual_analysis(
                sess.get("url"), sess.get("detected_stack"), combined_dom, sess.get("apis", []),
                payload.model_name, payload.context_size, payload.compute_strategy,
                payload.temperature, payload.max_tokens, steps,
                sdet_philosophy=payload.sdet_philosophy,
                coverage_mode=payload.coverage_mode
            )

            engine.run_synthesis_and_assembly(
                sess.get("url"), sess.get("detected_stack"), sess.get("is_auth"), combined_dom,
                sess.get("apis", []), payload.vectors, payload.model_name, payload.parallel,
                payload.context_size, payload.compute_strategy, payload.mcp_concurrency,
                payload.temperature, payload.max_tokens, steps, payload.custom_prompts,
                page_manifest=sess.get("page_manifest", []), username=sess.get("user", ""), password=sess.get("password", ""),
                sdet_philosophy=payload.sdet_philosophy, llm_contextual_analysis=contextual_analysis,
                coverage_mode=payload.coverage_mode, multi_resolution=payload.multi_resolution,
                matrix_depth=payload.matrix_depth, synthesis_engine=payload.synthesis_engine,
                selected_language=sess.get("selected_language", "Python"),
                selected_framework=sess.get("selected_framework", "Robot Framework + Pytest")
            )
        except Exception as e:
            trace = traceback.format_exc()
            with open("artifacts/logs/system_crash.log", "w", encoding="utf-8") as f: f.write(trace)
            with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f: json.dump({"status": "error", "error": str(e), "traceback": trace}, f)

    in_process_pool.submit(resume_task_worker)
    return {"status": "resumed"}

