@app.post("/api/chat/ask")
async def chat_ask(req: ChatRequest):
    def generate_chat():
        try:
            context_files = ["artifacts/reports/mrd.md"]
            if os.path.exists("artifacts/scripts"):
                for root, _, files in os.walk("artifacts/scripts"):
                    for file in files:
                        if file.endswith((".py", ".js", ".robot", ".md")):
                            context_files.append(os.path.join(root, file))
            
            system_prompt = "You are a Principal QA Automation Architect Assistant. Use the following project context to answer the user's questions or write new tests matching the established architecture. Only return code if explicitly asked. Keep answers concise.\n"
            system_prompt += "When you need to create or update a file based on the user's request, format your response exactly as follows:\n# FILE: <relative-path>\n```<lang>\n<content>\n```\nFor example: `# FILE: artifacts/scripts/my_test.py` followed by the markdown code block.\n\n"
            
            total_chars = 0
            MAX_CHARS = 12000
            for path in context_files:
                if os.path.exists(path) and os.path.getsize(path) < 150000:
                    try:
                        with open(path, "r", encoding="utf-8") as f:
                            content = f.read()
                            if total_chars + len(content) > MAX_CHARS:
                                break
                            system_prompt += f"=== {path} ===\n{content}\n\n"
                            total_chars += len(content)
                    except: pass
            
            messages = [{"role": "system", "content": system_prompt}]
            if req.history: messages.extend(req.history)
            messages.append({"role": "user", "content": req.message})
            
            ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/chat")
            if "/api/generate" in ollama_url: ollama_url = ollama_url.replace("/api/generate", "/api/chat")
            
            active_cfg = get_active_llm_config()
            vram_chat = probe_and_scale_vram_resources(req.model)
            
            # Use calibrated settings if set, else probe defaults
            scaled_ctx = (active_cfg.get("num_ctx") if active_cfg else None) or vram_chat.get("scaled_ctx", 8192)
            num_batch = (active_cfg.get("num_batch") if active_cfg else None) or vram_chat.get("num_batch", 1024)
            keep_alive_val = (active_cfg.get("keep_alive") if active_cfg else None) or "60m"
            num_threads = (active_cfg.get("threads") if active_cfg else None) or vram_chat.get("num_thread", 4)
            
            chat_options = {
                "num_ctx": scaled_ctx,
                "num_batch": num_batch,
                "num_thread": num_threads,
                "temperature": 0.2,
                "top_k": 20,
                "top_p": 0.5,
                "num_gpu": -1,
                "use_mmap": True,
                "f16_kv": True,
                "repeat_penalty": 1.0
            }
            response = requests.post(
                ollama_url,
                json={
                    "model": req.model, 
                    "messages": messages, 
                    "stream": True, 
                    "keep_alive": keep_alive_val,
                    "options": chat_options
                },
                stream=True,
                timeout=300
            )
            if response.status_code != 200:
                yield json.dumps({"error": f"Ollama API Error {response.status_code}"}) + "\n"
                return
            for line in response.iter_lines():
                if line: yield line.decode('utf-8') + "\n"
        except Exception as e:
            yield json.dumps({"error": str(e)}) + "\n"
    from fastapi.responses import StreamingResponse
    return StreamingResponse(generate_chat(), media_type="application/x-ndjson")

@app.get("/api/system/export")
def export_project():
    try:
        import zipfile, io
        from fastapi.responses import StreamingResponse
        zip_buffer = io.BytesIO()
        with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zf:
            for root, _, files in os.walk("artifacts"):
                for file in files:
                    file_path = os.path.join(root, file)
                    zf.write(file_path, os.path.relpath(file_path, "."))
        zip_buffer.seek(0)
        return StreamingResponse(
            zip_buffer,
            media_type="application/zip",
            headers={"Content-Disposition": "attachment; filename=qa_project_export.zip"}
        )
    except Exception as e:
        return {"status": "error", "message": str(e)}

