@app.get("/api/system/containers")
def get_all_containers():
    try:
        out = subprocess.check_output('docker ps -a --format "{{.Names}}|{{.State}}|{{.Status}}"', shell=True, timeout=5.0)
        lines = out.decode("utf-8").strip().split('\n')
        containers = []
        for line in lines:
            if not line: continue
            parts = line.split('|')
            if len(parts) == 3:
                name, state, status = parts
                c = {"name": name, "state": state, "status": status, "crash_logs": None}
                if state.lower() == "exited" and "Exited (0)" not in status:
                    try:
                        logs = subprocess.check_output(f"docker logs --tail 50 {name}", shell=True, stderr=subprocess.STDOUT, timeout=2.0).decode("utf-8", errors="replace")
                        c["crash_logs"] = logs
                    except Exception as e:
                        c["crash_logs"] = f"Could not fetch logs: {str(e)}"
                containers.append(c)
        return {"status": "success", "containers": containers}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.get("/api/system/docker-logs")
def get_docker_logs(container: str = "atp_core"):
    try:
        out = subprocess.check_output(f"docker logs --tail 200 {container}", shell=True, stderr=subprocess.STDOUT, timeout=2.0)
        return {"status": "success", "logs": {container: out.decode("utf-8", errors="replace")}}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.get("/api/system/docker-logs/all")
def get_all_docker_logs():
    """Fetches the tail logs for all active Docker containers in the stack."""
    try:
        # 1. Fetch all container names
        out = subprocess.check_output('docker ps -a --format "{{.Names}}"', shell=True, timeout=5.0)
        container_names = out.decode("utf-8").strip().split('\n')
        
        logs_data = {}
        # 2. Iterate through each container and fetch the last 50 lines
        for name in container_names:
            name = name.strip()
            if not name: continue
            
            try:
                log_out = subprocess.check_output(f"docker logs --tail 50 {name}", shell=True, stderr=subprocess.STDOUT, timeout=1.0)
                logs_data[name] = log_out.decode("utf-8", errors="replace")
            except Exception as e:
                logs_data[name] = f"Could not fetch logs: {str(e)}"
                
        return {"status": "success", "logs": logs_data}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/system/docker-restart")
def restart_docker(container: str = "atp_celery"):
    try:
        subprocess.check_output(f"docker restart {container}", shell=True, timeout=15.0)
        return {"status": "success", "message": f"{container} Restarted"}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/system/gpu-test")
def test_gpu_constraints(cfg: dict):
    ctx_size = cfg.get("context_size", 8192)
    # Estimate: ~1500MB base model overhead + 0.8MB per token. 
    req_vram_mb = int(1500 + (ctx_size * 0.8))
    
    telem = get_system_and_gpu_telemetry()
    vram_total = telem.get("gpu", {}).get("vram_total", 0)
    if vram_total == 0: vram_total = 8192 # Fallback assumption
    
    optimal_threads = max(1, int(vram_total // req_vram_mb))
    if req_vram_mb > vram_total:
        return {
            "status": "cpu_recommended", 
            "message": f"Requested context ({ctx_size} tokens) requires ~{req_vram_mb}MB VRAM. Your system reports {vram_total}MB available. We strongly recommend selecting 'Hybrid CPU+GPU (Combo)' or 'Force CPU' to avoid OOM crashes.",
            "optimal_threads": 1
        }
    else:
        return {
            "status": "gpu_suitable", 
            "message": f"VRAM Test Passed! Requested context fits perfectly inside the available GPU memory (~{req_vram_mb}MB / {vram_total}MB).",
            "optimal_threads": optimal_threads
        }

