        const [domElements, setDomElements] = React.useState([]);
        const [loadingDomElements, setLoadingDomElements] = React.useState(false);
        const [domRouteFilter, setDomRouteFilter] = React.useState('All');
        const [domUrlToIndex, setDomUrlToIndex] = React.useState('http://localhost:8000/');
        const [indexingDom, setIndexingDom] = React.useState(false);
        const [brokenLocatorInput, setBrokenLocatorInput] = React.useState('');
        const [healRouteInput, setHealRouteInput] = React.useState('/');
        const [healingResult, setHealingResult] = React.useState(null);
        const [isHealing, setIsHealing] = React.useState(false);
        const [isPatching, setIsPatching] = React.useState(false);
