                                            { key: 'LOAD', label: 'Load k6', icon: '⚡', color: 'from-yellow-600 to-amber-500' },
                                            { key: 'ACCEPTANCE', label: 'Acceptance', icon: '🤖', color: 'from-purple-600 to-pink-500' },
                                            { key: 'SECURITY', label: 'OWASP Sec', icon: '🛡️', color: 'from-red-600 to-rose-500' }
